   537      template <typename T>
   538      static float infer_delta (const hb_array_t<contour_point_t> points,
   539                                const hb_array_t<contour_point_t> deltas,
   540                                unsigned int target, unsigned int prev, unsigned int next)
   541      {
   542        float target_val = T::get (points[target]);
   543        float prev_val = T::get (points[prev]);
   544        float next_val = T::get (points[next]);
   545        float prev_delta = T::get (deltas[prev]);
   546        float next_delta = T::get (deltas[next]);
   547
   548        if (prev_val == next_val)
   549          return (prev_delta == next_delta) ? prev_delta : 0.f;
   550        else if (target_val <= hb_min (prev_val, next_val))
   551          return (prev_val < next_val) ? prev_delta : next_delta;
   552        else if (target_val >= hb_max (prev_val, next_val))
   553          return (prev_val > next_val) ? prev_delta : next_delta;
   554
   555        /* linear interpolation */
   556        float r = (target_val - prev_val) / (next_val - prev_val);
   557        return (1.f - r) * prev_delta + r * next_delta;
   558      }
