   868        bool phantom_only = !consumer.is_consuming_contour_points ();
   869        if (unlikely (!glyph_for_gid (gid).get_points ([this] (hb_codepoint_t gid) -> const Glyph { return this->glyph_for_gid (gid); },
   870                                                       font, all_points, phantom_only)))
   871          return false;
   872
   873        if (consumer.is_consuming_contour_points ())
   874        {
   875          for (unsigned point_index = 0; point_index + 4 < all_points.length; ++point_index)
   876            consumer.consume_point (all_points[point_index]);
   877          consumer.points_end ();
   878        }
