   880        /* Where to write phantoms, nullptr if not requested */
   881        contour_point_t *phantoms = consumer.get_phantoms_sink ();
   882        if (phantoms)
   883          for (unsigned i = 0; i < PHANTOM_COUNT; ++i)
   884            phantoms[i] = all_points[all_points.length - PHANTOM_COUNT + i];
   885
   886        return true;
   887      }
